/**
 * Maquetas de la pantalla que se está diseñando (M-029), con datos falsos; se abren con el extra
 * `maqueta`. Ahora: estilos de arte de FA.1 (A postal plana, B estampilla grabada, C arte de
 * chiva), cada uno con Villa de Leyva, Cartagena y Chapinero, en tamaño tarjeta y tamaño casilla.
 * Dibujos generados desde SVG; formato por línea: `relleno;contorno;ancho;d`, `C;d` abre un
 * recorte y `E` lo cierra.
 */
@Composable
fun Maqueta(letra: String) {
    val estilo = ESTILOS[letra]
    if (estilo == null) {
        Text("Sin maqueta $letra", Modifier.fillMaxSize().safeDrawingPadding().padding(20.dp))
        return
    }
    val dibujos = remember(letra) { estilo.map { (nombre, datos) -> nombre to vector(datos) } }
    Column(
        Modifier.fillMaxSize().background(Color(0xFF2E5E4E)).safeDrawingPadding().padding(12.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Text("Estilo $letra · ${NOMBRES[letra]}", color = Color.White, fontSize = 20.sp, fontWeight = FontWeight.Bold)
        for ((nombre, img) in dibujos) {
            Image(
                img, nombre,
                Modifier.weight(1f).aspectRatio(200f / 140f, matchHeightConstraintsFirst = true)
                    .clip(RoundedCornerShape(10.dp)),
            )
        }
        Text("Así en una casilla del tablero:", color = Color.White, fontSize = 14.sp)
        Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            for ((nombre, img) in dibujos) {
                Image(img, nombre, Modifier.width(36.dp).aspectRatio(200f / 140f).clip(RoundedCornerShape(2.dp)))
            }
        }
    }
}

private val NOMBRES = mapOf("A" to "Postal plana", "B" to "Estampilla grabada", "C" to "Arte de chiva")

private fun vector(datos: String): ImageVector {
    val b = ImageVector.Builder(
        defaultWidth = 200.dp, defaultHeight = 140.dp, viewportWidth = 200f, viewportHeight = 140f,
    )
    for (linea in datos.lineSequence().map(String::trim).filter(String::isNotEmpty)) {
        val p = linea.split(';')
        when (p[0]) {
            "C" -> b.addGroup(clipPathData = addPathNodes(p[1]))
            "E" -> b.clearGroup()
            else -> b.addPath(
                addPathNodes(p[3]), fill = color(p[0]), stroke = color(p[1]), strokeLineWidth = p[2].toFloat(),
                strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round,
            )
        }
    }
    return b.build()
}

private fun color(hex: String) =
    if (hex == "-") null else SolidColor(Color(0xFF000000 or hex.removePrefix("#").toLong(16)))

private val ESTILOS: Map<String, List<Pair<String, String>>> by lazy {
    mapOf(
    "A" to listOf("Villa de Leyva" to A_VILLA_DE_LEYVA, "Cartagena" to A_CARTAGENA, "Chapinero" to A_CHAPINERO),
    "B" to listOf("Villa de Leyva" to B_VILLA_DE_LEYVA, "Cartagena" to B_CARTAGENA, "Chapinero" to B_CHAPINERO),
    "C" to listOf("Villa de Leyva" to C_VILLA_DE_LEYVA, "Cartagena" to C_CARTAGENA, "Chapinero" to C_CHAPINERO),
    )
}

